// Regenerates frontend/functions/schema-bundle.mjs from the SQL files that the
// Node migration script also runs, so the Cloudflare deployment can repair its
// own schema without database credentials.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const sqlDir = path.join(root, 'backend/db/migrations');
const files = [path.join(root, 'backend/db/schema.sql'),
  ...fs.readdirSync(sqlDir).filter(f => f.endsWith('.sql')).sort().map(f => path.join(sqlDir, f))];

const REQUIRED = ['app_users','sessions','records','audit_events','record_history','documents',
  'approvals','ai_runs','auth_rate_limits','assistant_tasks','assistant_notes',
  'platform_conversations','platform_messages','agent_skills','agent_self_checks',
  'arena_battles','arena_responses','arena_artifacts','arena_ratings','agent_runs','expert_reviews'];

const parts = files.map(file => {
  const sql = fs.readFileSync(file, 'utf8');
  if (sql.includes('`') || sql.includes('${')) throw new Error(`${path.basename(file)} cannot be embedded in a template literal`);
  return { name: path.basename(file), sql };
});

const out = `// GENERATED by scripts/build-schema-bundle.mjs — do not edit by hand.
// Bundles the additive migration SQL so the Cloudflare deployment can repair its
// own schema on demand (see POST /api/admin/schema/repair).

export const SCHEMA_PARTS = [
${parts.map(p => `  { name: ${JSON.stringify(p.name)}, sql: \`${p.sql}\` },`).join('\n')}
];

// The tables /api/ready counts.
export const REQUIRED_TABLES = [
${REQUIRED.map(t => `  '${t}',`).join('\n')}
];

/** Statements that would destroy data. The bundle must never contain them. */
export function destructiveStatements(sql) {
  const found = [];
  const patterns = [
    /\\bDROP\\s+TABLE\\b/gi,
    /\\bDROP\\s+SCHEMA\\b/gi,
    /\\bTRUNCATE\\b/gi,
    /\\bDELETE\\s+FROM\\b/gi,
    /\\bDROP\\s+COLUMN\\b/gi,
    /\\bALTER\\s+TABLE\\s+\\w+\\s+DROP\\s+(?!CONSTRAINT\\b)/gi
  ];
  for (const p of patterns) for (const m of sql.matchAll(p)) found.push(m[0].trim());
  return found;
}
`;

fs.writeFileSync(path.join(root, 'frontend/functions/schema-bundle.mjs'), out);
console.log(`schema-bundle.mjs: ${parts.length} parts, ${REQUIRED.length} required tables`);
